sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float liftHue;
uniform float liftAmount;
uniform float liftLevel;
uniform float gammaHue;
uniform float gammaAmount;
uniform float gammaLevel;
uniform float gainHue;
uniform float gainAmount;
uniform float gainLevel;
uniform float offsetHue;
uniform float offsetAmount;
uniform float offsetLevel;
uniform float style;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float3 chroma(float hue) {
    float3 k = clamp(abs(fract(hue / 360.0 + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return k - luma(k);
}
float3 chroma6(float hue) {
    float3 k = clamp(abs(fract(hue / 360.0 + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return k - dot(k, float3(0.299, 0.587, 0.114));
}
float3 wheel(float3 o, float hue, float amount, float level, float weight) {
    return o + (level + 0.5 * amount * chroma6(hue)) * weight;
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    if (style > 0.5) {
        float3 o = base;
        float y = clamp(dot(o, float3(0.299, 0.587, 0.114)), 0.0, 1.0);
        o = wheel(o, gainHue, gainAmount, gainLevel, y * y);
        y = clamp(dot(o, float3(0.299, 0.587, 0.114)), 0.0, 1.0);
        o = wheel(o, gammaHue, gammaAmount, gammaLevel, 4.0 * y * (1.0 - y));
        y = clamp(dot(o, float3(0.299, 0.587, 0.114)), 0.0, 1.0);
        o = wheel(o, liftHue, liftAmount, liftLevel, (1.0 - y) * (1.0 - y));
        o = wheel(o, offsetHue, offsetAmount, offsetLevel, 1.0);
        return half4(half3(clamp(o, 0.0, 1.0)) * c.a, c.a);
    }
    float3 lift = 0.5 * chroma(liftHue) * liftAmount + liftLevel;
    float3 gain = 1.0 + chroma(gainHue) * gainAmount + gainLevel;
    float3 gamma = max(1.0 + chroma(gammaHue) * gammaAmount + gammaLevel, float3(0.01));
    float3 rgb = pow(max(gain * (base + lift * (1.0 - base)), 0.0), 1.0 / gamma);
    rgb += 0.5 * chroma(offsetHue) * offsetAmount + offsetLevel;
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
